function foodInputValue(v){return v===null||v===undefined?'':Math.round(v*100)/100;}
function foodFormNumber(k,v){const p=modalData.product;return $('per100').checked&&p&&p[k]!==null&&p[k]!==undefined&&Number(v)===Number(foodInputValue(p[k]))?p[k]:Number(v);}
let catalogFilter={query:'',category:'all',brand:'all',page:30};
function allFoods(){return [...(state.customFoods||[]),...FOOD_CATALOG,...recipeCatalogueFoods()];}
function recipeCatalogueFoods(){return RECIPES.map(r=>({id:r.id,recipeId:r.id,name:r.title,category:'ready',brand:'DAYMARK · приклад складу',quality:'recipe',unit:'portion',serving:1,...recipeEstimate(r),localized:true,emoji:'🍽'}));}
function foodById(id){return allFoods().find(x=>x.id===id);}
function safeSourceURL(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function foodSearchText(s){return String(s||'').toLocaleLowerCase('uk').replace(/[’ʼ']/g,'').replace(/ё/g,'е');}
function catalogMatches(p){const q=foodSearchText(catalogFilter.query),hay=foodSearchText([p.name,p.originalName,p.brand,p.aliases].join(' ')),terms=q.split(/[\s,]+/).filter(Boolean),cat=catalogFilter.category;return (cat==='all'||cat==='mine'&&p.quality==='user'||cat==='drink-all'&&(['drinks','alcohol'].includes(p.category)||p.unit==='ml')||p.category===cat)&&(catalogFilter.brand==='all'||p.brand===catalogFilter.brand)&&terms.every(t=>hay.includes(({'бургер':'бургер','латте':'лате','кофе':'кава','шаурма':'шаурма','макдональдс':'mcdonald','макдональдз':'mcdonald','мcdonalds':'mcdonald','суши':'суш','овсянка':'вівся','курица':'кур','шампанское':'шампан','творог':'сир'}[t]||t)));}
function catalogueSearch(q=''){catalogFilter.query=q;catalogFilter.page=30;modalData={mode:'catalog'};openModal('МІЙ ЩОДЕННИК / '+num(FOOD_CATALOG.length)+' ПОЗИЦІЙ','<h2 class="modal-title">Усе, що є<br>у твоєму житті.</h2><p class="modal-sub">3 815 позицій із джерел і 100 ідей рецептів. Домашня їжа, фастфуд, кафе й напої. Звіряй точний продукт, спосіб приготування та порцію.</p><div class="catalog-fast"><button data-action="drink-builder">☕ Зібрати свій напій</button><button data-action="custom-food">＋ Свій продукт / заклад</button></div><label class="recipe-search">'+icon('search')+'<input id="foodSearch" type="search" value="'+esc(q)+'" placeholder="Шаурма, суші, піца, вино, McDonald’s…" aria-label="Пошук їжі й напоїв"></label><div class="catalog-controls"><label class="form-label">Категорія<select id="catalogCategory">'+[['all','Уся база'],['mine','Мої продукти'],['restaurant','Заклади України'],['drink-all','Усі напої'],...Object.entries(FOOD_CATEGORIES).filter(([k])=>!['restaurant'].includes(k))].map(([k,n])=>'<option value="'+k+'" '+(catalogFilter.category===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="form-label">Джерело / заклад<select id="catalogBrand"><option value="all">Усі джерела</option>'+[...new Set(allFoods().map(p=>p.brand))].map(n=>'<option '+(n===catalogFilter.brand?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label></div><p class="catalog-coverage">Заклади: McDonald’s Україна, KFC Україна, Lviv Croissants і окремі позиції Sushi Master (Харків). Це не повне меню всіх ресторанів країни.</p><div id="catalogCount" class="filter-note"></div><div id="searchResults" class="catalog-results"></div><div id="catalogMore"></div><details class="catalog-method"><summary>Джерела й точність</summary><p>Дані закладу — опублікована стандартна порція. Ciqual — середній склад продуктів у Франції, а не етикетка будь-якого українського бренду. Частина міжнародного довідника має оригінальні англійські назви; доступний пошук українськими ключовими словами. Етикетка твого продукту й точна вага важливіші.</p><p>Позначки «дані закладу», «довідник», «за складом» і «мій продукт» показують походження. Невідомі БЖВ залишаються невідомими. Дата перевірки джерел: 23.10.2026; це збережена версія, не живе оновлення меню.</p></details>');$('foodSearch').oninput=e=>{catalogFilter.query=e.target.value;catalogFilter.page=30;renderCatalogResults();};$('catalogCategory').onchange=e=>{catalogFilter.category=e.target.value;catalogFilter.page=30;renderCatalogResults();};$('catalogBrand').onchange=e=>{catalogFilter.brand=e.target.value;catalogFilter.page=30;renderCatalogResults();};renderCatalogResults();}
function renderCatalogResults(q){if(q!==undefined)catalogFilter.query=q;let list=allFoods().filter(catalogMatches);if(!catalogFilter.query&&catalogFilter.category==='all'&&catalogFilter.brand==='all'){const groups=[list.filter(p=>p.quality==='user'),list.filter(p=>p.quality==='reference'&&p.localized).sort((a,b)=>['staples','dairy','meat','fish','veg','fruit','ready','nuts','sweets','sauces','snacks','drinks','alcohol','other'].indexOf(a.category)-['staples','dairy','meat','fish','veg','fruit','ready','nuts','sweets','sauces','snacks','drinks','alcohol','other'].indexOf(b.category)),...['McDonald’s Україна','KFC Україна','Lviv Croissants','Sushi Master · Харків'].map(b=>list.filter(p=>p.brand===b)),list.filter(p=>p.quality==='recipe')];const mixed=[];while(groups.some(g=>g.length))for(const g of groups)if(g.length)mixed.push(g.shift());list=[...mixed,...list.filter(p=>p.quality==='reference'&&!p.localized)];}$('catalogCount').textContent='Знайдено: '+num(list.length)+' · показано '+Math.min(list.length,catalogFilter.page);$('searchResults').innerHTML=list.slice(0,catalogFilter.page).map(p=>'<button class="catalog-item" data-action="'+(p.recipeId?'recipe-open':'pick-food')+'" data-id="'+p.id+'"><span class="food-visual">'+esc(p.emoji||'◌')+'</span><span><strong>'+esc(p.name)+'</strong><small>'+esc(p.brand)+' · '+(p.quality==='restaurant'?'дані закладу':p.quality==='user'?'мій продукт':p.quality==='recipe'?'за складом рецепта':'довідник')+'</small><em>'+num(p.kcal,1)+' ккал / '+(p.unit==='portion'?'порція рецепта':'100 '+(p.unit==='ml'?'мл':'г'))+(p.quality==='restaurant'?' · порція '+num(p.serving)+' '+(p.unit==='ml'?'мл':'г'):'')+'</em></span><b>＋</b></button>').join('')||'<div class="empty">Такої позиції поки немає.<br>Можна внести етикетку або дані свого закладу.</div>';$('catalogMore').innerHTML=list.length>catalogFilter.page?'<button class="btn ghost full" data-action="catalog-more">Показати ще 30 ↓</button>':'';}
function foodProvenance(p){return {id:p.id,brand:p.brand||'',url:safeSourceURL(p.url),quality:p.quality||'reference',checked:p.checked||'',originalName:p.originalName||'',unit:p.unit||'g',serving:p.serving||100,review:p.review||''};}
function productNotice(p){const ref=foodProvenance(p);return '<div class="source-card"><b>'+esc(ref.brand)+'</b><span>'+(ref.quality==='restaurant'?'Опубліковано закладом. Стандартна порція: '+num(ref.serving)+' '+(ref.unit==='ml'?'мл':'г')+'. Фактична порція може відрізнятися.':ref.quality==='calculated'?'Розраховано з введеного складу або калорійності твоєї етикетки. Це модель; БЖВ можуть бути невідомими.':ref.quality==='user'?'Твій власний запис за етикеткою / меню.':'Середнє довідкове значення. Обирай саме цей спосіб приготування; для бренду звір етикетку.')+'</span>'+(ref.originalName?'<details><summary>Повна назва в джерелі</summary><p>'+esc(ref.originalName)+'</p></details>':'')+(ref.url?'<a href="'+esc(ref.url)+'" target="_blank" rel="noopener">Відкрити джерело ↗</a>':'')+(ref.review?'<p>'+esc(ref.review)+'</p>':'')+'<small>Перевірено '+esc(ref.checked||'тобою')+' · невідомі БЖВ не дорівнюють нулю.</small></div>';}
function catalogMeal(p){if(!p)return;mealModal('catalog',p);modalData.meal.source=p.quality==='restaurant'?'restaurant':p.quality==='user'?'user-food':'reference';modalData.meal.unit=p.unit||'g';modalData.meal.foodRef=foodProvenance(p);const g=$('portionGrams');g.value=p.serving||100;const bar=document.createElement('div');bar.className='portion-presets';bar.innerHTML=[.5,1,2].map(n=>'<button type="button" data-action="food-serving" data-value="'+(p.serving||100)*n+'">'+num(n,1)+' '+(p.quality==='restaurant'?'порц.':'× '+num(p.serving||100)+' '+(p.unit==='ml'?'мл':'г'))+'</button>').join('');$('mealForm').prepend(bar);portionResult();}
function customFoodModal(){openModal('МОЯ БАЗА / ЕТИКЕТКА АБО МЕНЮ','<h2 class="modal-title">Твоя їжа —<br>теж у базі.</h2><form id="customFoodForm"><label class="form-label">Назва<input name="name" maxlength="140" required placeholder="Продукт, страва або напій"></label><label class="form-label">Бренд / заклад<input name="brand" maxlength="80" placeholder="Мій продукт"></label><div class="form-pair"><label class="form-label">Значення на 100<select name="unit"><option value="g">грамів</option><option value="ml">мілілітрів</option></select></label><label class="form-label">Звична порція<input name="serving" type="number" min=".1" max="10000" step="any" value="100" required></label></div><div class="form-pair">'+[['kcal','Ккал'],['p','Білки, г'],['f','Жири, г'],['c','Вуглеводи, г']].map(([k,n])=>'<label class="form-label">'+n+' / 100<input name="'+k+'" type="number" min="0" max="'+(k==='kcal'?10000:100)+'" step="any" '+(k==='kcal'?'required':'')+' placeholder="'+(k==='kcal'?'З етикетки':'Може бути невідомо')+'"></label>').join('')+'</div><label class="form-label">Посилання на меню · необов’язково<input type="url" name="url" placeholder="https://…"></label><p class="note">Внось значення на 100 г / мл. Якщо меню дає дані лише на всю порцію, скористайся швидким записом у щоденнику. Мої продукти зберігаються тільки у твоїй базі.</p><button class="btn blue full">Зберегти продукт у мою базу</button></form>');}
function saveCustomFood(v){const name=v.name?.trim(),kcal=Number(v.kcal),serving=Number(v.serving);if(!name||!Number.isFinite(kcal)||kcal<0||kcal>10000||!Number.isFinite(serving)||serving<=0||serving>10000)return;state.customFoods=state.customFoods||[];if(state.customFoods.length>=500){toast('У власній базі вже 500 продуктів');return;}const p={id:'own-'+uid(),name,brand:v.brand?.trim()||'Мій продукт',category:v.unit==='ml'?'drinks':'other',unit:v.unit==='ml'?'ml':'g',basis:100,serving,kcal,p:v.p===''?null:Number(v.p),f:v.f===''?null:Number(v.f),c:v.c===''?null:Number(v.c),quality:'user',url:safeSourceURL(v.url),checked:today(),localized:true,emoji:v.unit==='ml'?'🥤':'◌'};state.customFoods.push(p);persist();catalogMeal(p);toast('Продукт у твоїй базі. Обери порцію.');}
const DRINK_TYPES={espresso:{name:'Еспресо',coffee:30,milk:0,volume:30},americano:{name:'Американо',coffee:30,milk:0,volume:200},latte:{name:'Лате',coffee:30,milk:220,volume:300},icedlatte:{name:'Айс лате',coffee:30,milk:150,volume:300},cappuccino:{name:'Капучино',coffee:30,milk:140,volume:200},flatwhite:{name:'Флет-вайт',coffee:60,milk:120,volume:180},raf:{name:'Раф: молоко й вершки',coffee:30,milk:120,cream:40,volume:250},matcha:{name:'Матча лате',matcha:2,milk:200,volume:250},icedmatcha:{name:'Айс матча лате',matcha:2,milk:150,volume:300},tea:{name:'Чай чорний',base:'18154',volume:250},greentea:{name:'Чай зелений',base:'18155',volume:250},cocoa:{name:'Какао з молоком',cocoa:6,milk:200,volume:250},wine:{name:'Вино / ігристе',wine:true,volume:150},mulled:{name:'Глінтвейн за своїм складом',wine:true,sugar:10,volume:200},beer:{name:'Пиво / сидр',base:'5001',volume:330},juice:{name:'Сік / фреш',base:'2013',volume:250},gin:{name:'Джин-тонік за складом',spirit:'1002',spiritQty:50,mixer:'18344',mixerQty:150,volume:250},vodka:{name:'Горілка із соком за складом',spirit:'1008',spiritQty:50,mixer:'2013',mixerQty:150,volume:250}};
const DRINK_MILKS={'none':'Без молока','19033':'Молоко напівзнежирене','19016':'Молоко незбиране','19050':'Молоко знежирене','18899':'Вівсяний напій без цукру','18107':'Мигдалевий напій без цукру','18900':'Соєвий напій без добавок','18904':'Рисовий напій'};
function drinkData(code){return FOOD_CATALOG.find(x=>x.id==='ciq-'+code);}
function drinkBuilder(kind='latte'){if(!DRINK_TYPES[kind])kind='latte';const d=DRINK_TYPES[kind];modalData={mode:'drink',kind};openModal('НАПОЇ / ТВІЙ СКЛАД','<h2 class="modal-title">Не просто «кава».<br>Саме твоя.</h2><form id="drinkForm"><label class="form-label">Що п’єш?<select id="drinkKind" name="kind">'+Object.entries(DRINK_TYPES).map(([k,x])=>'<option value="'+k+'" '+(kind===k?'selected':'')+'>'+x.name+'</option>').join('')+'</select></label><div class="form-pair"><label class="form-label">Розмір склянки / порції, мл<input name="volume" type="number" min="1" max="3000" step="1" value="'+d.volume+'" required></label><label class="form-label">Кількість порцій<input name="count" type="number" min=".1" max="20" step=".1" value="1" required></label></div>'+(!d.wine&&!d.spirit?'<label class="form-label">Молоко / рослинний напій<select name="milk">'+Object.entries(DRINK_MILKS).map(([k,n])=>'<option value="'+k+'" '+(k===(d.milk?'19033':'none')?'selected':'')+'>'+n+'</option>').join('')+'</select></label><div class="form-pair"><label class="form-label">Саме молока, мл<input name="milkQty" type="number" min="0" max="3000" value="'+(d.milk||0)+'" step="any"></label><label class="form-label">Вершків 30%, г<input name="creamQty" type="number" min="0" max="500" value="'+(d.cream||0)+'" step="any"></label></div>':'')+(d.coffee?'<label class="form-label">Еспресо, мл<input name="coffeeQty" type="number" min="0" max="500" value="'+d.coffee+'" step="any"></label>':'')+(d.matcha?'<label class="form-label">Порошок чистої матча, г<input name="matchaQty" type="number" min="0" max="30" value="2" step="any"><small>Енергія порошку — орієнтир 237 ккал / 100 г, за матеріалом виробника Ichizen. БЖВ порошку не опубліковані тут і залишаться невідомими.</small></label>':'')+(d.cocoa?'<label class="form-label">Какао без цукру, г<input name="cocoaQty" type="number" min="0" max="100" value="6" step="any"></label>':'')+(d.wine?'<label class="form-label">Яке вино?<select name="wine">'+[['5215','Біле сухе'],['5214','Червоне'],['5216','Рожеве'],['1006','Солодке'],['5201','Біле ігристе'],['5207','Шампанське']].map(([k,n])=>'<option value="'+k+'">'+n+'</option>').join('')+'</select></label><label class="form-label">Вина в порції, мл<input name="wineQty" type="number" min="0" max="3000" value="'+(kind==='mulled'?180:d.volume)+'" step="any"><small>У глінтвейні окремо враховуємо доданий цукор. Нагрівання не означає повного зникнення алкоголю.</small></label>':'')+(kind==='beer'?'<label class="form-label">Тип<select name="beer">'+[['5001','Пиво 4–5%'],['5002','Пиво понад 8%'],['5009','Пшеничне пиво'],['5030','Безалкогольне без доданого цукру'],['5006','Сухий сидр'],['5007','Солодкий сидр']].map(([k,n])=>'<option value="'+k+'">'+n+'</option>').join('')+'</select></label>':'')+(d.spirit?'<div class="form-pair"><label class="form-label">'+(d.spirit==='1002'?'Джину':'Горілки')+', мл<input name="spiritQty" type="number" min="0" max="1000" value="50" step="any"></label><label class="form-label">'+(d.mixer==='18344'?'Тоніку':'Соку')+', мл<input name="mixerQty" type="number" min="0" max="3000" value="150" step="any"></label></div>':'')+'<div class="form-pair"><label class="form-label">Доданий цукор, г<input name="sugar" type="number" min="0" max="200" value="'+(d.sugar||0)+'" step="any"><small>Без цукру — 0; чайна ложка ≈ 4 г.</small></label><label class="form-label">Сироп, г<input name="syrup" type="number" min="0" max="200" value="0" step="any"><small>Модель: 65% цукру, уточни за етикеткою.</small></label></div><details><summary class="small">Є точні дані готового напою?</summary><label class="form-label">Ккал на 100 мл за етикеткою<input name="labelKcal" type="number" min="0" max="2000" step="any" placeholder="Замінить модель складу"><small>Якщо ввів / ввела тільки ккал, БЖВ не домислюємо.</small></label></details><div id="drinkResult" class="drink-result" aria-live="polite"></div><p class="form-error" id="drinkError" role="alert"></p><p class="filter-note">Показуємо модель твого складу. Для довідкових рідин припускаємо 1 мл ≈ 1 г; піна, лід і вода не замінюють введений обсяг молока. Напій не радимо й не оцінюємо — лише записуємо. Алкоголь містить енергію, яка не відображається сумою БЖВ.</p><button class="btn blue full" type="submit">Уточнити й додати до щоденника ↗</button></form>');$('drinkKind').onchange=e=>drinkBuilder(e.target.value);$('drinkForm').oninput=renderDrinkResult;renderDrinkResult();}
function drinkEstimate(v){const d=DRINK_TYPES[v.kind]||DRINK_TYPES.latte,parts=[],volume=Number(v.volume),count=Number(v.count),n=k=>Number(v[k]||0);let error='';const add=(code,qty,label)=>{const p=drinkData(code);if(qty>0&&p)parts.push({name:label||p.name,qty,code,kcal:p.kcal,p:p.p,f:p.f,c:p.c});};if(d.coffee)add('18071',n('coffeeQty'));if(v.milk&&v.milk!=='none')add(v.milk,n('milkQty'));add('19417',n('creamQty'));if(d.matcha&&n('matchaQty')>0)parts.push({name:'Порошок матча: орієнтир Ichizen',qty:n('matchaQty'),code:'matcha',kcal:237,p:null,f:null,c:null});if(d.cocoa)add('18100',n('cocoaQty'));if(d.wine)add(v.wine||'5215',n('wineQty'));if(d.spirit){add(d.spirit,n('spiritQty'));add(d.mixer,n('mixerQty'));}if(d.base){const base=v.kind==='beer'?v.beer||d.base:d.base;add(base,Math.max(0,volume-(v.milk!=='none'?n('milkQty'):0)-n('creamQty')));}add('31016',n('sugar'));if(n('syrup')>0){const p=drinkData('31016');parts.push({name:'Сироп: модель 65% цукру',qty:n('syrup'),code:'syrup-model',kcal:p.kcal*.65,p:p.p===null?null:p.p*.65,f:p.f===null?null:p.f*.65,c:p.c===null?null:p.c*.65});}const liquid=(d.coffee?n('coffeeQty'):0)+(v.milk&&v.milk!=='none'?n('milkQty'):0)+n('creamQty')+(d.wine?n('wineQty'):0)+(d.spirit?n('spiritQty')+n('mixerQty'):0);if(liquid>volume)error='Рідких інгредієнтів більше за обсяг порції. Збільш склянку або уточни кількість.';const totals={kcal:0,p:0,f:0,c:0};for(const k of Object.keys(totals)){totals[k]=parts.some(p=>p[k]===null)?null:parts.reduce((s,p)=>s+p[k]*p.qty/100,0)*count;}if(v.labelKcal!==''&&v.labelKcal!==undefined){totals.kcal=Number(v.labelKcal)*volume/100*count;totals.p=totals.f=totals.c=null;}if(volume*count>10000)error='Для одного запису обери не більше 10 000 мл.';if(!Number.isFinite(volume)||volume<=0||!Number.isFinite(count)||count<=0)error='Вкажи обсяг і кількість порцій.';return{...totals,parts,volume:volume*count,count,name:d.name,error};}
function renderDrinkResult(){const v=Object.fromEntries(new FormData($('drinkForm')).entries()),x=drinkEstimate(v);$('drinkError').textContent=x.error;$('drinkResult').innerHTML='<span>Твоя порція · '+num(x.volume)+' мл</span><strong>≈ '+num(x.kcal)+' <small>ккал</small></strong><p>'+['p','f','c'].map((k,i)=>['Б','Ж','В'][i]+' '+(x[k]===null?'—':num(x[k],1)+' г')).join(' · ')+'</p><small>'+x.parts.map(p=>esc(p.name)+' '+num(p.qty*x.count,1)+' г / мл').join(' + ')+'</small><p class="filter-note">Вода / лід — решта обсягу. Зміна розміру склянки сама по собі не збільшує введене молоко чи сироп.</p>';}
function saveDrink(v){const x=drinkEstimate(v);if(x.error){$('drinkError').textContent=x.error;return;}const m={id:uid(),name:x.name+' · '+num(x.volume)+' мл',type:'drink',grams:x.volume,unit:'ml',kcal:round(x.kcal),p:x.p===null?null:round(x.p),f:x.f===null?null:round(x.f),c:x.c===null?null:round(x.c),source:'calculated',emoji:'🥤',foodRef:{id:'drink-'+uid(),brand:v.labelKcal!==''?'Моя етикетка':'Конструктор напою · модель складу',quality:'calculated',url:'https://doi.org/10.5281/zenodo.17550133',checked:today(),originalName:x.parts.map(p=>p.name+' '+num(p.qty*x.count,1)+' г / мл').join(' + '),unit:'ml',serving:x.volume}};mealModal('manual',null,m);}
